#include "cvc_config.h"
#include "cvc_json.h"
#include "cvc_glob.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>
static int jkey_ascii(const CvcJString*k,char*out,size_t cap){if(k->n+1>cap)return 0;for(size_t i=0;i<k->n;i++)if(k->p[i]==0||k->p[i]>=0x80)return 0;memcpy(out,k->p,k->n);out[k->n]=0;return 1;}
void cvc_config_init_defaults(CvcConfig*c){c->show_diffstat=1;cvc_strvec_init(&c->tracking_include);cvc_strvec_init(&c->tracking_exclude);cvc_strvec_init(&c->diffstat_include);cvc_strvec_init(&c->diffstat_exclude);cvc_strvec_push(&c->tracking_include,"**");cvc_strvec_push(&c->diffstat_include,"**");}
void cvc_config_free(CvcConfig*c){cvc_strvec_free(&c->tracking_include);cvc_strvec_free(&c->tracking_exclude);cvc_strvec_free(&c->diffstat_include);cvc_strvec_free(&c->diffstat_exclude);}
static int patterns(CvcJson*j,CvcStrVec*v,const char*where){if(!j||j->type!=J_ARRAY)return cvc_errorf("config.json: %s must be an array",where);cvc_strvec_free(v);cvc_strvec_init(v);for(size_t i=0;i<j->u.array.n;i++){CvcJson*x=j->u.array.v[i];if(x->type!=J_STRING)return cvc_errorf("config.json: %s elements must be strings",where);if(!x->u.string.n||memchr(x->u.string.p,0,x->u.string.n))return cvc_errorf("config.json: %s contains empty/NUL pattern",where);char*s=cvc_xstrndup((const char*)x->u.string.p,x->u.string.n);if(!cvc_glob_validate(s)){free(s);return cvc_errorf("config.json: invalid glob in %s",where);}cvc_strvec_push(v,s);free(s);}return 0;}
static int reject_unknown(const CvcJson*o,const char*const*allowed,size_t n,const char*where){for(size_t i=0;i<o->u.object.n;i++){const CvcJString*k=&o->u.object.v[i].key;if(memchr(k->p,0,k->n))return cvc_errorf("config.json: NUL in key at %s",where);int ok=0;for(size_t a=0;a<n;a++){size_t z=strlen(allowed[a]);if(k->n==z&&!memcmp(k->p,allowed[a],z)){ok=1;break;}}if(!ok){char tmp[160];if(jkey_ascii(k,tmp,sizeof(tmp)))return cvc_errorf("config.json: unknown key %s.%s",where,tmp);return cvc_errorf("config.json: unknown/non-ASCII key at %s",where);}}return 0;}
int cvc_config_load(const char*path,CvcConfig*c){CvcBuf b;if(cvc_read_file_nofollow(path,&b)<0)return cvc_errorf("cannot read config.json: %s",strerror(errno));CvcJson*j=NULL;char*err=NULL;if(cvc_json_parse(b.data,b.len,&j,&err)<0){cvc_buf_free(&b);int r=cvc_errorf("config.json: %s",err);free(err);return r;}cvc_buf_free(&b);CvcConfig tmp;cvc_config_init_defaults(&tmp);int rc=-1;if(j->type!=J_OBJECT){cvc_errorf("config.json: top level must be object");goto out;}const char*top[]={"format_version","save","tracking","diffstat"};if(reject_unknown(j,top,4,"root")<0)goto out;CvcJson*fv=cvc_json_obj_get(j,"format_version");if(!fv||fv->type!=J_NUMBER||fv->u.number.n!=1||fv->u.number.p[0]!='1'){cvc_errorf("config.json: format_version must be integer token 1");goto out;}CvcJson*sv=cvc_json_obj_get(j,"save");if(sv){if(sv->type!=J_OBJECT){cvc_errorf("config.json: save must be object");goto out;}const char*a[]={"show_diffstat"};if(reject_unknown(sv,a,1,"save")<0)goto out;CvcJson*x=cvc_json_obj_get(sv,"show_diffstat");if(x){if(x->type!=J_BOOL){cvc_errorf("config.json: save.show_diffstat must be boolean");goto out;}tmp.show_diffstat=x->u.boolean;}}
CvcJson*tr=cvc_json_obj_get(j,"tracking");if(tr){if(tr->type!=J_OBJECT){cvc_errorf("config.json: tracking must be object");goto out;}const char*a[]={"include","exclude"};if(reject_unknown(tr,a,2,"tracking")<0)goto out;CvcJson*x=cvc_json_obj_get(tr,"include");if(x&&patterns(x,&tmp.tracking_include,"tracking.include")<0)goto out;x=cvc_json_obj_get(tr,"exclude");if(x&&patterns(x,&tmp.tracking_exclude,"tracking.exclude")<0)goto out;}
CvcJson*ds=cvc_json_obj_get(j,"diffstat");if(ds){if(ds->type!=J_OBJECT){cvc_errorf("config.json: diffstat must be object");goto out;}const char*a[]={"include","exclude"};if(reject_unknown(ds,a,2,"diffstat")<0)goto out;CvcJson*x=cvc_json_obj_get(ds,"include");if(x&&patterns(x,&tmp.diffstat_include,"diffstat.include")<0)goto out;x=cvc_json_obj_get(ds,"exclude");if(x&&patterns(x,&tmp.diffstat_exclude,"diffstat.exclude")<0)goto out;}
*c=tmp;rc=0;out:if(rc<0)cvc_config_free(&tmp);cvc_json_free(j);return rc;}
static void print_arr(const CvcStrVec*v){putchar('[');for(size_t i=0;i<v->n;i++){if(i)printf(", ");putchar('"');for(const unsigned char*p=(const unsigned char*)v->v[i];*p;p++){if(*p=='"'||*p=='\\')putchar('\\');putchar(*p);}putchar('"');}putchar(']');}
void cvc_config_show(const CvcConfig*c){printf("format_version = 1\n");printf("save.show_diffstat = %s\n",c->show_diffstat?"true":"false");printf("tracking.include = ");print_arr(&c->tracking_include);putchar('\n');printf("tracking.exclude = ");print_arr(&c->tracking_exclude);putchar('\n');printf("diffstat.include = ");print_arr(&c->diffstat_include);putchar('\n');printf("diffstat.exclude = ");print_arr(&c->diffstat_exclude);putchar('\n');}
